import java.io.*;

// FileReader can throw FileNotFoundException (checked) -> must declare or catch
String readFirstLine(String path) throws IOException { // declared with throws
    try (BufferedReader br = new BufferedReader(new FileReader(path))) {
        return br.readLine();
    }
    // Without the throws (or a try-catch) this would NOT compile.
}
```

Checked exceptions (`IOException`, `SQLException`) model recoverable external failures, so the compiler makes the caller acknowledge them.

```java
// NumberFormatException extends RuntimeException (unchecked)
int parseAge(String raw) {
    return Integer.parseInt(raw); // may throw at runtime; no throws needed
}

int age = parseAge("oops"); // compiles fine, blows up at runtime -> it's a bug to fix
```

Unchecked exceptions (`NullPointerException`, `IllegalArgumentException`) signal programming errors, so Java does not force handling — you fix the cause instead.

// Unchecked exception for business logic errors
public class OrderNotFoundException extends RuntimeException {
    public OrderNotFoundException(String message) {
        super(message); // pass message to RuntimeException
    }

    public OrderNotFoundException(String message, Throwable cause) {
        super(message, cause); // chain exceptions
    }
}

// Usage in service layer
@Service
public class OrderService {
    public Order findOrder(Long orderId) {
        return repository.findById(orderId)
            .orElseThrow(() -> new OrderNotFoundException(
                "Order not found with ID: " + orderId));
    }
}

// Handling in REST controller
@RestControllerAdvice
public class GlobalExceptionHandler {
    @ExceptionHandler(OrderNotFoundException.class)
    public ResponseEntity<String> handleOrderNotFound(OrderNotFoundException ex) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body(ex.getMessage());
    }
}

// Old approach: manual finally block
public String readFileLegacy(String path) throws IOException {
    BufferedReader reader = null;
    try {
        reader = new BufferedReader(new FileReader(path));
        return reader.readLine();
    } catch (IOException e) {
        System.err.println("Error reading file");
        throw e;
    } finally {
        if (reader != null) {
            reader.close(); // always called, even if return was executed
        }
    }
}

// Modern approach: try-with-resources (Java 7+)
public String readFileModern(String path) throws IOException {
    try (var reader = new BufferedReader(new FileReader(path))) {
        return reader.readLine(); // reader.close() called automatically
    } catch (IOException e) {
        System.err.println("Error reading file");
        throw e;
    }
    // No finally needed! Try-with-resources handles cleanup
}

public class CollectionModificationExample {
    public static void main(String[] args) {
        var orders = new ArrayList<>(List.of("Order1", "Order2", "Order3", "Order4"));

        // WRONG: modification during for-each iteration
        // for (var order : orders) {
        //     if (order.startsWith("Order2")) {
        //         orders.remove(order); // ConcurrentModificationException!
        //     }
        // }

        // Solution 1: removeIf (best for simple conditions)
        orders.removeIf(order -> order.startsWith("Order2"));

        // Solution 2: Iterator.remove() for complex logic
        var iterator = orders.iterator();
        while (iterator.hasNext()) {
            var order = iterator.next();
            if (order.equals("Order3")) {
                iterator.remove(); // safe removal through iterator
            }
        }

        // Solution 3: collect changes, apply after iteration
        var toRemove = orders.stream()
            .filter(order -> order.startsWith("Order"))
            .toList();
        orders.removeAll(toRemove);
    }
}
